mod support;
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
use serde_json::{json,Value};use tower::ServiceExt;
use std::sync::{Arc,atomic::AtomicBool};
use video_kadr_backend::domain::{filmcraft_source_pixels,transition_kernel_pack::{context::RenderContext,image::Image}};
fn request(body:Value)->Request<Body>{Request::builder().method("POST").uri("/api/compositions/filmcraft/preview-frame").header("content-type","application/json").body(Body::from(serde_json::to_vec(&body).unwrap())).unwrap()}
fn fixture()->Value{serde_json::from_str(include_str!("fixtures/filmcraft-source-masks.json")).unwrap()}
#[tokio::test]
async fn program_frame_matches_original_composed_mask_pixels(){
 let (state,_dir)=support::make_state(false,false).await;let app=support::router(state);let fixture=fixture();
 let context=RenderContext::new_with_budget(Arc::new(AtomicBool::new(false)),1,4096,1024*1024).unwrap();
 let cases:Vec<_>=fixture["cases"].as_array().unwrap().iter().filter(|c|c["scale"]==1.&&c["effect"]=="invert"&&c["mask_mode"]=="Add"&&c["profile"]==1).take(3).collect();assert_eq!(cases.len(),3);
 for case in cases{
  let response=app.clone().oneshot(request(json!({"document":serde_json::to_string(&case["document"]).unwrap(),"sequenceId":case["sequence"].as_u64().unwrap().to_string(),"timeTicks":case["at"].as_i64().unwrap().to_string()}))).await.unwrap();assert_eq!(response.status(),StatusCode::OK);
  let body:Value=serde_json::from_slice(&to_bytes(response.into_body(),2*1024*1024).await.unwrap()).unwrap();
  assert_eq!(body["kind"],"sequence");assert_eq!(body["ptsTicks"],case["at"].as_i64().unwrap().to_string());assert_eq!(body["width"],case["width"]);assert_eq!(body["height"],case["height"]);
  let mut image=Image::new(case["width"].as_u64().unwrap()as usize,case["height"].as_u64().unwrap()as usize);for(p,b)in image.px.iter_mut().zip(case["bits"].as_array().unwrap()){*p=f32::from_bits(b.as_u64().unwrap()as u32)}
  let output=filmcraft_source_pixels::encode_srgb(&context,&image).unwrap();let expected:String=output.surface().rgba.iter().map(|b|format!("{b:02x}")).collect();assert_eq!(body["rgbaHex"],expected);
 }
}
#[tokio::test]
async fn preview_bounds_output_and_preserves_exact_time(){
 let(state,_dir)=support::make_state(false,false).await;let mut document=fixture()["cases"][0]["document"].clone();let seq=&mut document["project"]["items"]["6"]["kind"]["Sequence"];seq["settings"]["width"]=json!(1920);seq["settings"]["height"]=json!(1080);seq["video_tracks"]=json!([]);
 let app=support::router(state);let response=app.clone().oneshot(request(json!({"document":document,"sequenceId":"6","timeTicks":"9007199254740993","effects":false,"captions":false}))).await.unwrap();assert_eq!(response.status(),StatusCode::OK);let body:Value=serde_json::from_slice(&to_bytes(response.into_body(),2*1024*1024).await.unwrap()).unwrap();assert_eq!(body["ptsTicks"],"9007199254740993");assert_eq!(body["width"],480);assert_eq!(body["height"],270);assert_eq!(body["rgbaHex"].as_str().unwrap().len(),480*270*8);assert_eq!(body["effects"],false);
 let response=app.oneshot(request(json!({"document":document,"sequenceId":"6","timeFrames":"24"}))).await.unwrap();assert_eq!(response.status(),StatusCode::OK);let body:Value=serde_json::from_slice(&to_bytes(response.into_body(),2*1024*1024).await.unwrap()).unwrap();assert_eq!(body["ptsTicks"],"254016000000");
}
#[tokio::test]
async fn preview_rejects_ambiguous_time_and_unconnected_file_sources(){
 let(state,_dir)=support::make_state(false,false).await;let app=support::router(state);let mut document=fixture()["cases"][0]["document"].clone();
 for time in [json!({}),json!({"timeTicks":"0","timeFrames":"0"}),json!({"timeTicks":"9223372036854775808"})]{let mut input=json!({"document":document,"sequenceId":"6"});input.as_object_mut().unwrap().extend(time.as_object().unwrap().clone());let response=app.clone().oneshot(request(input)).await.unwrap();assert_eq!(response.status(),StatusCode::BAD_REQUEST);}
 document["project"]["items"]["1"]["kind"]["Media"]["media"]=json!({"File":{"path":"/untrusted/source.mov"}});
 let response=app.oneshot(request(json!({"document":document,"sequenceId":"6","timeTicks":"0"}))).await.unwrap();assert_eq!(response.status(),StatusCode::BAD_REQUEST);let error=String::from_utf8(to_bytes(response.into_body(),65536).await.unwrap().to_vec()).unwrap();assert!(error.contains("file source provider is not connected"),"{error}");
}
#[tokio::test]
async fn library_png_flows_through_effect_masks_and_rejects_missing_bindings(){
 use video_kadr_backend::library::MediaEntry;
 let (state,dir)=support::make_state(false,false).await;
 let fixture:Value=serde_json::from_str(include_str!("fixtures/filmcraft-image-source.json")).unwrap();let case=fixture["cases"].as_array().unwrap().iter().find(|c|c["kind"]=="mask"&&c["variant"]==2&&c["scale"]==1.).unwrap();
 let source=&case["images"]["1"];let variant=source["pattern"].as_u64().unwrap();let rgba:Vec<u8>=(0..source["width"].as_u64().unwrap()*source["height"].as_u64().unwrap()).flat_map(|i|[((i*37+11)%256)as u8,((i*73+51)%256)as u8,((i*19+83)%256)as u8,match variant{0=>255,1=>128,_=>[0,1,64,128,255][i as usize%5]}]).collect();image::RgbaImage::from_raw(source["width"].as_u64().unwrap()as u32,source["height"].as_u64().unwrap()as u32,rgba).unwrap().save(dir.path().join("sources/pattern.png")).unwrap();
 assert!(state.library.add(MediaEntry::from_result("source",&json!({"id":"image-source","filename":"pattern.png","mediaType":"image"}))).await);
 let app=support::router(state.clone());let input=json!({"document":serde_json::to_string(&case["document"]).unwrap(),"sequenceId":case["sequence"].as_u64().unwrap().to_string(),"timeTicks":case["at"].as_i64().unwrap().to_string(),"sources":{"1":"image-source"}});
 let response=app.clone().oneshot(request(input.clone())).await.unwrap();assert_eq!(response.status(),StatusCode::OK);let body:Value=serde_json::from_slice(&to_bytes(response.into_body(),2*1024*1024).await.unwrap()).unwrap();
 let context=RenderContext::new_with_budget(Arc::new(AtomicBool::new(false)),1,4096,1024*1024).unwrap();let mut image=Image::new(case["width"].as_u64().unwrap()as usize,case["height"].as_u64().unwrap()as usize);for(p,b)in image.px.iter_mut().zip(case["bits"].as_array().unwrap()){*p=f32::from_bits(b.as_u64().unwrap()as u32)}let output=filmcraft_source_pixels::encode_srgb(&context,&image).unwrap();assert_eq!(body["rgbaHex"],output.surface().rgba.iter().map(|b|format!("{b:02x}")).collect::<String>());
 let mut missing=input.clone();missing["sources"]=json!({"1":"not-present"});assert_eq!(app.clone().oneshot(request(missing)).await.unwrap().status(),StatusCode::NOT_FOUND);
 let mut invalid=input.clone();invalid["sources"]=json!({"6":"image-source"});let response=app.clone().oneshot(request(invalid)).await.unwrap();assert_eq!(response.status(),StatusCode::BAD_REQUEST);
 let owner=state.db.register_auth_user("preview-image-owner","shared test password").await.unwrap().unwrap();let outsider=state.db.register_auth_user("preview-image-outsider","shared test password").await.unwrap().unwrap();let space=state.db.create_space(&owner.user.username,"Preview images").await.unwrap();state.db.create_space_composition_project("Image claim",&json!({"schemaVersion":1,"sources":{"image-source":{"id":"image-source"}}}),&["image-source".into()],&owner.user.username,&space.id).await.unwrap();
 assert_eq!(app.clone().oneshot(request(input.clone())).await.unwrap().status(),StatusCode::UNAUTHORIZED);
 let mut denied=request(input.clone());denied.headers_mut().insert("authorization",format!("Bearer {}",outsider.token).parse().unwrap());assert_eq!(app.clone().oneshot(denied).await.unwrap().status(),StatusCode::FORBIDDEN);
 let mut allowed=request(input);allowed.headers_mut().insert("authorization",format!("Bearer {}",owner.token).parse().unwrap());assert_eq!(app.oneshot(allowed).await.unwrap().status(),StatusCode::OK);

}
